import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { mkdtemp, utimes, mkdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const run = promisify(execFile);
const dir = await mkdtemp(join(tmpdir(), 'state-'));
const env = { ...process.env, STATE_DIR: join(dir, 'nested', 'state') }; // missing dir gets created
const cwd = '/tmp/bot-test';
const child = async (op, arg, iso = '') => JSON.parse((await run('node', ['worker.mjs', op, arg, iso], { env, cwd })).stdout);
const reserve = (req, iso) => child('reserve', JSON.stringify(req), iso);
const T0 = '2026-10-22T10:00:00.000Z';
const at = (min) => new Date(Date.parse(T0) + min * 60_000).toISOString();
const base = { maxPerWindow: 3, windowHours: 24, minGapMinutes: 0 };

// 1. Concurrency across processes: 48 attempts, cap 3 -> exactly 3 allowed.
const race = await Promise.all(Array.from({ length: 48 }, () => reserve({}, T0)));
const won = race.filter((r) => r.allowed);
assert.equal(won.length, 3, 'exactly 3 sends under race');
assert.ok(race.filter((r) => !r.allowed).every((r) => r.reason === 'window_limit_reached' && r.reservationId === null));
assert.ok(won.every((r) => r.reason === null && typeof r.reservationId === 'string'));
console.log('ok 1: 3 of 48 concurrent reserves allowed, denials carry reason');

// 2. History survives across processes (fresh process sees the 3 sends).
const r2 = await reserve(base, at(60 * 24 - 1));
assert.equal(r2.reason, 'window_limit_reached');
console.log('ok 2: new process sees prior history, window still full');

// 3. Release from another process frees one slot; second release is a no-op.
assert.equal(await child('release', won[0].reservationId), true);
assert.equal(await child('release', won[0].reservationId), false);
const r3 = await reserve(base, at(60 * 24 - 1));
assert.equal(r3.allowed, true);
console.log('ok 3: released slot reusable; double release returns false');

// 4. Sliding window: cap 2 per 1h. Sends at 0 and 10 min; 20 min denied; 61 min allowed (0 has aged out, 10 still counts).
const w = { maxPerWindow: 2, windowHours: 1, minGapMinutes: 0 };
const L = 'lead_window';
const lr = (req, iso) => child('reserve', JSON.stringify({ userId: L, ...req }), iso);
assert.equal((await lr(w, at(0))).allowed, true);
assert.equal((await lr(w, at(10))).allowed, true);
assert.equal((await lr(w, at(20))).reason, 'window_limit_reached');
assert.equal((await lr(w, at(61))).allowed, true);
assert.equal((await lr(w, at(61))).reason, 'window_limit_reached');
console.log('ok 4: sliding window reopens as each send ages out');

// 5. Gap: minGap 90 min. Send at 0; 30 min denied with distinct reason; 91 min allowed.
const g = { maxPerWindow: 10, windowHours: 24, minGapMinutes: 90 };
const LG = 'lead_gap';
const gr = (iso) => child('reserve', JSON.stringify({ userId: LG, ...g }), iso);
assert.equal((await gr(at(0))).allowed, true);
const gDenied = await gr(at(30));
assert.equal(gDenied.reason, 'min_gap_not_elapsed');
assert.notEqual(gDenied.reason, 'window_limit_reached');
assert.equal((await gr(at(91))).allowed, true);
console.log('ok 5: min gap enforced with its own reason code');

// 6. Gap is symmetric: out-of-order caller clock 40 min before an existing send is denied.
assert.equal((await gr(at(-40))).reason, 'min_gap_not_elapsed');
console.log('ok 6: gap also holds for earlier timestamps');

// 7. Leads are independent.
assert.equal((await child('reserve', JSON.stringify({ userId: 'other', ...g }), at(30))).allowed, true);
console.log('ok 7: other leads unaffected');

// 8. Stale lock from a crashed worker is cleared; a fresh lock is respected.
const { createHash } = await import('node:crypto');
const key = createHash('sha256').update('lead_stale').digest('hex');
await mkdir(join(env.STATE_DIR, 'locks', `${key}.lock`), { recursive: true });
const old = new Date(Date.now() - 60_000);
await utimes(join(env.STATE_DIR, 'locks', `${key}.lock`), old, old);
assert.equal((await child('reserve', JSON.stringify({ userId: 'lead_stale', ...base }), T0)).allowed, true);
console.log('ok 8: stale lock broken');

// 9. Invalid input is rejected, not silently allowed.
await assert.rejects(run('node', ['worker.mjs', 'reserve', JSON.stringify({ userId: '', ...base }), T0], { env, cwd }));
console.log('ok 9: invalid input throws');
console.log('ALL PASSED');
EOF
